package shorts

// news_publish_auth.go lets ONE endpoint — /api/admin/news/publish — accept a
// narrower credential than the INTERNAL_SERVICE_SECRET.
//
// The internal secret opens every /api/admin/* route (broadcasts, job runs,
// enrichment approvals, …). Handing it to an automation that only needs to
// publish an article would grant all of that. NEWS_PUBLISH_TOKEN is a separate
// secret (generated by Terraform into Secret Manager, see
// terraform/modules/shorts-api/main.tf) that this middleware accepts on the
// publish route and that no other route knows about, so leaking it can publish
// or re-publish a MERGED article and nothing else.
//
// The internal secret still works here too: it is a superset, and the admin
// console's server actions already hold it.

import (
	"crypto/subtle"
	"net/http"
	"os"
	"strings"
)

// newsPublishTokenHeader is the header the scoped token travels in. A Bearer
// token is also accepted, so a plain `Authorization: Bearer <token>` works.
const newsPublishTokenHeader = "x-news-publish-token"

// newsPublishTokenActor is the audit identity for a call authenticated by the
// scoped token rather than by an admin session.
const newsPublishTokenActor = "news-publish-token"

// newsPublishAuthMiddleware accepts NEWS_PUBLISH_TOKEN, and otherwise defers to
// adminAuthMiddleware unchanged (including its fail-closed production rule).
func newsPublishAuthMiddleware(next http.HandlerFunc) http.HandlerFunc {
	admin := adminAuthMiddleware(next)
	return func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodOptions && validNewsPublishToken(r) {
			// The caller cannot choose its own audit name with this token: the
			// log line must say which credential was used.
			r.Header.Set("x-admin-actor", newsPublishTokenActor)
			next(w, r)
			return
		}
		admin(w, r)
	}
}

// validNewsPublishToken reports whether the request carries the configured
// scoped token. An unset token matches nothing — never the empty string.
func validNewsPublishToken(r *http.Request) bool {
	expected := os.Getenv("NEWS_PUBLISH_TOKEN")
	if expected == "" {
		return false
	}
	presented := r.Header.Get(newsPublishTokenHeader)
	if presented == "" {
		if auth := r.Header.Get("Authorization"); strings.HasPrefix(auth, "Bearer ") {
			presented = strings.TrimPrefix(auth, "Bearer ")
		}
	}
	if presented == "" {
		return false
	}
	return subtle.ConstantTimeCompare([]byte(presented), []byte(expected)) == 1
}
